import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private class FastScanner {
    private val br = BufferedReader(InputStreamReader(System.`in`))
    private var st = StringTokenizer("")

    fun next(): String {
        while (!st.hasMoreTokens()) {
            st = StringTokenizer(br.readLine())
        }
        return st.nextToken()
    }

    fun nextInt(): Int = next().toInt()
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val commands = fs.next()

    var x = 0
    var y = 0
    var answer = 0L
    val frequencies = HashMap<Long, Long>()

    fun key(x: Int, y: Int): Long =
        (x.toLong() shl 32) xor (y.toLong() and 0xffffffffL)

    frequencies[key(0, 0)] = 1L

    for (i in 0 until n) {
        when (commands[i]) {
            'U' -> y++
            'R' -> x++
            'D' -> y--
            'L' -> x--
        }

        val position = key(x, y)
        val count = frequencies.getOrDefault(position, 0L)
        answer += count
        frequencies[position] = count + 1
    }

    print(answer)
}

